static struct regmap * felix_request_regmap_by_name ( struct felix * felix , const char * resource_name ) { struct ocelot * ocelot = & felix -> ocelot ; struct resource res ; int i ; if ( ! felix -> info -> resources ) { return dev_get_regmap ( ocelot -> dev -> parent , resource_name ) ; } for ( i = 0 ; i < felix -> info -> num_resources ; i ++ ) { if ( strcmp ( resource_name , felix -> info -> resources [ i ] . name ) ) { continue ; } res . start += felix -> switch_base ; res . end += felix -> switch_base ; return ocelot_regmap_init ( ocelot , & res ) ; } return ERR_PTR ( - ENOENT ) ; } 